import (
	"context"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/proto"

	"github.com/milvus-io/birdwatcher/states/kv"
	"github.com/milvus-io/milvus/pkg/v3/proto/indexpb"
)

type saveRecordingKV struct {
	kv.MetaKV
	saveKeys   []string
	saveValues []string
}

func (k *saveRecordingKV) Save(ctx context.Context, key, value string) error {
	k.saveKeys = append(k.saveKeys, key)
	k.saveValues = append(k.saveValues, value)
	return nil
}

func TestWriteRepairedIndex(t *testing.T) {
	t.Run("marshal failure does not write to etcd", func(t *testing.T) {
		cli := &saveRecordingKV{}
		index := &indexpb.FieldIndex{
			IndexInfo: &indexpb.IndexInfo{
				CollectionID: 100,
				IndexID:      200,
				// invalid UTF-8 makes proto.Marshal fail.
				IndexName: "\xff\xfe\x00\x80invalid",
			},
		}

		err := writeRepairedIndex(cli, "by-dev/meta", index)

		require.Error(t, err)
		assert.Empty(t, cli.saveKeys, "Save must not be called when marshaling fails")
	})

	t.Run("valid index is saved", func(t *testing.T) {
		cli := &saveRecordingKV{}
		index := &indexpb.FieldIndex{
			IndexInfo: &indexpb.IndexInfo{
				CollectionID: 100,
				IndexID:      200,
				IndexName:    "index_name",
			},
		}

		err := writeRepairedIndex(cli, "by-dev/meta", index)

		require.NoError(t, err)
		require.Len(t, cli.saveKeys, 1)
		assert.Equal(t, "by-dev/meta/field-index/100/200", cli.saveKeys[0])

		saved := &indexpb.FieldIndex{}
		require.NoError(t, proto.Unmarshal([]byte(cli.saveValues[0]), saved))
		assert.Equal(t, index.GetIndexInfo().GetIndexName(), saved.GetIndexInfo().GetIndexName())
	})
}

package reset

import (
	"encoding/base64"
	"encoding/binary"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	wplog "github.com/zilliztech/woodpecker/woodpecker/log"

	"github.com/milvus-io/birdwatcher/states/etcd/common"
	"github.com/milvus-io/milvus-proto/go-api/v3/commonpb"
)

// The consume-checkpoint id we write must be decodable by the same unmarshaler
// Milvus uses. birdwatcher mirrors that logic in common.GetMessageIDString, so a
// round-trip through it proves the encoding is right rather than merely stable.
func TestWALPositionRoundTripsThroughDecoder(t *testing.T) {
	cases := []struct {
		wal        string
		decoderKey string
		wantDecode string
	}{
		{"woodpecker", "wp", "0/0"},
		{"wp", "wp", "0/0"},
		{"kafka", "kafka", "0"},
		{"rocksmq", "rmq", "0"},
	}

	for _, tc := range cases {
		t.Run(tc.wal, func(t *testing.T) {
			pos, err := buildWALPosition(tc.wal)
			require.NoError(t, err)

			got := common.GetMessageIDString(tc.decoderKey, pos.msgID.Id)
			assert.Equal(t, tc.wantDecode, got,
				"consume-checkpoint id must decode back to the expected position")
		})
	}
}

func TestWALPositionWoodpeckerEncodings(t *testing.T) {
	earliest, err := buildWALPosition("woodpecker")
	require.NoError(t, err)
	assert.Equal(t, commonpb.WALName_WoodPecker, earliest.walName)

	// raw bytes are what goes into msgpb.MsgPosition.MsgID
	id, err := wplog.DeserializeLogMessageId(earliest.raw)
	require.NoError(t, err)
	assert.Equal(t, int64(0), id.SegmentId)
	assert.Equal(t, int64(0), id.EntryId)

	// consume-checkpoint id is base64 over exactly those bytes
	decoded, err := base64.StdEncoding.DecodeString(earliest.msgID.Id)
	require.NoError(t, err)
	assert.Equal(t, earliest.raw, decoded)
	assert.Equal(t, commonpb.WALName_WoodPecker, earliest.msgID.WALName)
}

func TestWALPositionInt64RawIsLittleEndian(t *testing.T) {
	pos, err := buildWALPosition("kafka")
	require.NoError(t, err)
	require.Len(t, pos.raw, 8)
	assert.Equal(t, int64(0), int64(binary.LittleEndian.Uint64(pos.raw)))
}

func TestWALPositionRejectsUnknownWAL(t *testing.T) {
	_, err := buildWALPosition("nats")
	assert.ErrorContains(t, err, "unsupported --target-wal")

	_, err = buildWALPosition("")
	assert.ErrorContains(t, err, "--target-wal is required")
}

// woodpecker's earliest id serializes to zero bytes, because protobuf omits
// zero-valued scalars. Milvus relies on this: msgdispatcher only treats an empty
// MsgID as seekable when WALName says WoodPecker (pkg/mq/msgdispatcher/
// dispatcher.go). So the empty encoding is correct, but only if we also set
// WALName — which is exactly what birdcatcher's rename path forgets to do.
func TestWoodpeckerEarliestIsEmptyBytesButNamed(t *testing.T) {
	pos, err := buildWALPosition("woodpecker")
	require.NoError(t, err)

	assert.Empty(t, pos.raw, "woodpecker earliest serializes to zero bytes")
	assert.Empty(t, pos.msgID.Id, "and therefore to an empty base64 string")
	assert.Equal(t, commonpb.WALName_WoodPecker, pos.walName,
		"WALName must still be set, or milvus cannot tell an empty id from an unset one")
	assert.Equal(t, commonpb.WALName_WoodPecker, pos.msgID.WALName)
}

package repair

import (
	"context"
	"fmt"

	"github.com/cockroachdb/errors"
	"github.com/samber/lo"
	"google.golang.org/protobuf/encoding/protojson"

	"github.com/milvus-io/birdwatcher/framework"
	"github.com/milvus-io/birdwatcher/models"
	"github.com/milvus-io/birdwatcher/states/etcd/common"
	"github.com/milvus-io/milvus-proto/go-api/v3/schemapb"
	"github.com/milvus-io/milvus/pkg/v3/proto/streamingpb"
)

type WALRecoveryStorageParam struct {
	framework.ExecutionParam `use:"repair wal-recovery-storage" desc:"recover wal from storage"`
}

func (c *ComponentRepair) WALRecoveryStorageCommand(ctx context.Context, p *WALRecoveryStorageParam) error {
	metas, err := common.ListWALDistribution(ctx, c.client, c.basePath, "")
	if err != nil {
		return errors.Wrap(err, "failed to list wal distribution")
	}

	needFix := make([]*streamingpb.VChannelMeta, 0)
	for _, meta := range metas {
		pchannel := meta.Channel.Name
		storage, err := common.ListWALRecoveryStorage(ctx, c.client, c.basePath, pchannel)
		if err != nil {
			return errors.Wrap(err, "failed to list wal recovery storage")
		}
		for _, vchannel := range storage.VChannels {
			if len(vchannel.CollectionInfo.Schemas) == 0 {
				// If the schema is lost, we need to fix it.
				needFix = append(needFix, vchannel)
			}
		}
	}

	if len(needFix) == 0 {
		fmt.Println("no need to fix wal recovery storage")
		return nil
	}
	collectionIDs := make(map[int64]bool)
	for _, vchannel := range needFix {
		collectionIDs[vchannel.CollectionInfo.CollectionId] = true
	}
	collections, err := common.ListCollections(ctx, c.client, c.basePath, func(collection *models.Collection) bool {
		_, ok := collectionIDs[collection.GetProto().GetID()]
		return ok
	})
	if err != nil {
		return errors.Wrap(err, "failed to list collections")
	}
	collectionMap := make(map[int64]*models.Collection)
	for _, collection := range collections {
		collectionMap[collection.GetProto().GetID()] = collection
	}
	for _, vchannel := range needFix {
		if _, ok := collectionMap[vchannel.CollectionInfo.CollectionId]; !ok {
			return errors.Errorf("collection not found, collectionID: %d", vchannel.CollectionInfo.CollectionId)
		}
	}

	if p.Run {
		fmt.Println("run mode, will fix wal recovery storage...")
	} else {
		fmt.Println("dry run mode, will not fix wal recovery storage...")
	}
	for _, vchannel := range needFix {
		collection := collectionMap[vchannel.CollectionInfo.CollectionId]
		collectionProto := collectionMap[vchannel.CollectionInfo.CollectionId].GetProto()
		schema := &streamingpb.CollectionSchemaOfVChannel{
			Schema: &schemapb.CollectionSchema{
				Name:               collectionProto.Schema.Name,
				Description:        collectionProto.Schema.Description,
				AutoID:             collectionProto.Schema.AutoID,
				Fields:             collectionProto.Schema.Fields,
				EnableDynamicField: collectionProto.Schema.EnableDynamicField,
				Properties:         collectionProto.Properties,
				Functions: lo.Map(collection.Functions, func(function *models.Function, _ int) *schemapb.FunctionSchema {
					return function.GetProto()
				}),
				DbName:            collectionProto.Schema.DbName,
				StructArrayFields: collectionProto.Schema.StructArrayFields,
			},
			CheckpointTimeTick: 0,
			State:              streamingpb.VChannelSchemaState_VCHANNEL_SCHEMA_STATE_NORMAL,
		}
		fmt.Println("--------------------------------")
		if !p.Run {
			schemaJSON, err := protojson.MarshalOptions{
				EmitUnpopulated:   true,
				EmitDefaultValues: true,
			}.Marshal(schema)
			if err != nil {
				return errors.Wrap(err, "failed to marshal schema")
			}
			fmt.Printf("%s will be fixed with schema \n %s\n", vchannel.Vchannel, string(schemaJSON))
		} else {
			if err := c.fixWALRecoveryStorage(ctx, vchannel, schema); err != nil {
				fmt.Printf("failed to fix wal recovery storage for vchannel %s, error: %s\n", vchannel.Vchannel, err.Error())
				return err
			}
			fmt.Printf("%s fixed\n", vchannel.Vchannel)
		}
		fmt.Println("--------------------------------")
	}
	return nil
}

func (c *ComponentRepair) fixWALRecoveryStorage(ctx context.Context, vchannel *streamingpb.VChannelMeta, schema *streamingpb.CollectionSchemaOfVChannel) error {
	return common.SaveSchemaForVChannel(ctx, c.client, c.basePath, vchannel, schema)
}

